"use client";

import * as React from "react";
import { Toggle as TogglePrimitive } from "@base-ui/react/toggle";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { focusRing, pressScale, pressedBevel } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Burnished Toggle: a pill that holds its state. Off, it is muted text, or
 * a pill pressed into a recessed well for the outline variant. Pressed, it
 * rises as a graphite bevel in full ink.
 */
const toggleVariants = cva(
  [
    "inline-flex shrink-0 select-none items-center justify-center gap-1.5 whitespace-nowrap rounded-full",
    "font-semibold tracking-[0.016em] text-muted-foreground",
    "transition-[box-shadow,color] duration-base ease-(--ease-out)",
    pressScale,
    focusRing,
    "data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
    pressedBevel,
    "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        default:
          "bg-transparent [@media(hover:hover)_and_(pointer:fine)]:hover:not-data-[pressed]:text-foreground",
        outline:
          "bg-(image:--fill-well) shadow-(--bevel-well) [@media(hover:hover)_and_(pointer:fine)]:hover:not-data-[pressed]:text-foreground",
      },
      size: {
        sm: "h-8 px-3 text-xs",
        default: "h-9 px-4 text-sm",
        lg: "h-11 px-5 text-[0.9375rem]",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

/** Burnished Toggle on Base UI: one pill that stays pressed. */
const Toggle = React.forwardRef<
  HTMLButtonElement,
  WithClassName<TogglePrimitive.Props> & VariantProps<typeof toggleVariants>
>(({ className, variant, size, ...props }, ref) => (
  <TogglePrimitive
    ref={ref}
    data-slot="toggle"
    className={cn(toggleVariants({ variant, size, className }))}
    {...props}
  />
));
Toggle.displayName = "Toggle";

export { Toggle, toggleVariants };
